using System.Net;
using System.Net.Sockets;
using System.Text.Json;

namespace WinClient.Core.Firewall;

internal sealed record RecordedRule(string Name, string? Program, string[] RemoteAddress, string? Protocol, string? RemotePort);
internal sealed record RecordedNode(string Program, IReadOnlyList<IPAddress> Ips, int Hy2Port, int RealityPort);

/// <summary>断网保护恢复记录(killswitch-state.json)里换登录放行要读的两样:模式和套用时记下的放行规则。只读不写。</summary>
internal sealed record KillSwitchRecord(string Mode, IReadOnlyList<RecordedRule> Rules)
{
    /// <summary>文件不在、读不了、不是 JSON 对象时返回 null;没写模式的记录按全部流量("global")算。</summary>
    public static KillSwitchRecord? Read(string path)
    {
        try
        {
            if (!File.Exists(path)) return null;
            using var json = JsonDocument.Parse(File.ReadAllText(path));
            var root = json.RootElement;
            if (root.ValueKind != JsonValueKind.Object) return null;
            var mode = root.TryGetProperty("mode", out var value) && value.ValueKind == JsonValueKind.String ? value.GetString()! : "global";
            var rules = new List<RecordedRule>();
            if (root.TryGetProperty("rules", out var list))
                foreach (var item in Items(list))
                    if (item.ValueKind == JsonValueKind.Object && Text(item, "Name") is { Length: > 0 } name)
                        rules.Add(new(name, Text(item, "Program"),
                            item.TryGetProperty("RemoteAddress", out var remote) ? Items(remote).Select(Scalar).OfType<string>().ToArray() : Array.Empty<string>(),
                            Text(item, "Protocol"), Text(item, "RemotePort")));
            return new(mode, rules.AsReadOnly());
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException or JsonException or InvalidOperationException) { return null; }
    }

    // Windows PowerShell 写出的数组有三种样子:数组;带 value 数组的对象;只有一项时的单个值。
    private static JsonElement[] Items(JsonElement value)
    {
        if (value.ValueKind == JsonValueKind.Array) return value.EnumerateArray().ToArray();
        if (value.ValueKind == JsonValueKind.Object)
            return value.TryGetProperty("value", out var inner) && inner.ValueKind == JsonValueKind.Array
                ? inner.EnumerateArray().ToArray() : Array.Empty<JsonElement>();
        return value.ValueKind is JsonValueKind.Null or JsonValueKind.Undefined ? Array.Empty<JsonElement>() : new[] { value };
    }

    private static string? Scalar(JsonElement value) => value.ValueKind switch
    {
        JsonValueKind.String => value.GetString(),
        JsonValueKind.Number => value.GetRawText(),
        _ => null
    };

    private static string? Text(JsonElement item, string name) => item.TryGetProperty(name, out var value) ? Scalar(value) : null;

    /// <summary>记录里有没有一条和它一样的放行:名字、程序(不分大小写)、远端地址、协议、远端端口都一样。</summary>
    public bool Has(AddRule rule) => Rules.Any(item => item.Name == rule.Name &&
        string.Equals(item.Program, rule.Program, StringComparison.OrdinalIgnoreCase) &&
        item.RemoteAddress.Order(StringComparer.OrdinalIgnoreCase).SequenceEqual(
            (rule.RemoteAddress ?? Array.Empty<string>()).Order(StringComparer.OrdinalIgnoreCase), StringComparer.OrdinalIgnoreCase) &&
        string.Equals(item.Protocol, rule.Protocol, StringComparison.OrdinalIgnoreCase) && item.RemotePort == rule.RemotePort);

    /// <summary>从两条节点放行读回内核路径、节点地址和两个端口;缺一样或格式不对返回 null。</summary>
    public RecordedNode? Node()
    {
        var tcp = Rules.FirstOrDefault(item => item.Name == KillSwitchPlanner.NodePrefix + "Tcp");
        var udp = Rules.FirstOrDefault(item => item.Name == KillSwitchPlanner.NodePrefix + "Udp");
        if (tcp?.Program is not { Length: > 0 } program || udp is null || !Path.IsPathFullyQualified(program)) return null;
        var ips = new List<IPAddress>();
        foreach (var text in tcp.RemoteAddress)
        {
            if (!IPAddress.TryParse(text, out var ip) || ip.AddressFamily != AddressFamily.InterNetwork) return null;
            ips.Add(ip);
        }
        if (ips.Count == 0 || !Port(tcp.RemotePort, out var reality) || !Port(udp.RemotePort, out var hy2)) return null;
        return new(program, ips.AsReadOnly(), hy2, reality);
    }

    private static bool Port(string? text, out int port) =>
        int.TryParse(text, System.Globalization.NumberStyles.None, System.Globalization.CultureInfo.InvariantCulture, out port) && port is >= 1 and <= 65535;
}

